ValidationRule.errorConditionFormula:
/* Nirvana Quote Line VR */
AND(
SBQQ__Quote__r.Has_Bypass_Site__c, SBQQ__Quote__r.BypassValidation__c=false, NOT($User.Locked_Quotes_Editor__c),
$Profile.Name <> "System Administrator", $Profile.Name <> "API/ADMIN/NON MFA",
NOT(ISCLONE()), NOT(ISNEW()),
ISPICKVAL(SBQQ__Quote__r.ApprovalStatus__c, "Approved"),
/* Block only when none of these allowed fields are changing */
NOT(ISCHANGED(PM_Approved__c)), NOT(ISCHANGED(Quote_Approved__c)), NOT(ISCHANGED(SBQQ__Hidden__c)), NOT(ISCHANGED(ITC_Status__c)), NOT(ISCHANGED(SBQQ__Group__c)), NOT(ISCHANGED(Group_Region__c)), NOT(ISCHANGED(Created_Date_4_QAD__c)), NOT(ISCHANGED(Pre_Nirvana_QL_Sync_to_ERP__c)), NOT(ISCHANGED(List_Unit_Price_1_Approved__c)), NOT(ISCHANGED(List_Unit_Price_2_Approved__c)), NOT(ISCHANGED(List_Unit_Price_3_Approved__c)), NOT(ISCHANGED(List_Unit_Price_4_Approved__c)), NOT(ISCHANGED(List_Unit_Price_5_Approved__c)),
/* Quote totals */ NOT(ISCHANGED(SBQQ__ListTotal__c)), NOT(ISCHANGED(SBQQ__CustomerTotal__c)), NOT(ISCHANGED(SBQQ__NetTotal__c)),
/* Discount fields */ NOT(ISCHANGED(SBQQ__Discount__c)), NOT(ISCHANGED(SBQQ__AdditionalDiscount__c)), NOT(ISCHANGED(SBQQ__AdditionalQuantity__c)), NOT(ISCHANGED(AdditionalDiscountUnit__c)), NOT(ISCHANGED(SBQQ__AdditionalDiscountAmount__c)), NOT(ISCHANGED(SBQQ__CompoundDiscountRate__c)),
NOT(ISCHANGED(Disc_1__c)), NOT(ISCHANGED(Disc_2__c)), NOT(ISCHANGED(Disc_3__c)), NOT(ISCHANGED(Disc_Type_1__c)), NOT(ISCHANGED(Disc_Type_2__c)), NOT(ISCHANGED(Disc_Type_3__c)), NOT(ISCHANGED(Discount_Percentage__c)), NOT(ISCHANGED(Discount_Calculation__c)),
NOT(ISCHANGED(SBQQ__TotalDiscountAmount__c)), NOT(ISCHANGED(SBQQ__TotalDiscountRate__c)),
/* Pricing fields */ NOT(ISCHANGED(SBQQ__Quantity__c)), NOT(ISCHANGED(SBQQ__ListPrice__c)), NOT(ISCHANGED(SBQQ__CustomerPrice__c)), NOT(ISCHANGED(SBQQ__NetPrice__c)), NOT(ISCHANGED(SBQQ__RegularPrice__c)),
/* Other allowed fields */ NOT(ISCHANGED(CurrencyIsoCode)), NOT(ISCHANGED(Customer_ERP_ID__c)), NOT(ISCHANGED(Target_BP_Number__c)), NOT(ISCHANGED(SBQQ__Product__c)), NOT(ISCHANGED(Product_Description__c)), NOT(ISCHANGED(SBQQ__Description__c)), NOT(ISCHANGED(SR_Product__c)), NOT(ISCHANGED(QAD_Product_Comment__c)) )
